        elNote: T('Göreli sertlik · temsili', 'Relative stiffness · representative', 'Rigidez relativa · representativa'), cdNote: T('Kırmızı probe doğru, mavi uzağa', 'Red toward the probe, blue away', 'Rojo hacia la sonda, azul alejándose'),
        pdNote: T('Akımın gücü · yön yok', 'Flow strength · no direction', 'Intensidad del flujo · sin dirección'), pwNote: T('Uzun eksende açı verin', 'Add an angle in long axis', 'Añada un ángulo en eje largo'), mNote: T('Şerit zamana karşı hareket', 'Strip: motion over time', 'Franja: movimiento en el tiempo'),
